'use strict';
const SITE_NAME='Kellner Sim Golf League';
let data=window.LEAGUE_STARTER,model,tab='schedule',week=1,statScope='regular',sortBy='gross';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=id=>data.Teams.find(t=>t.id===id)?.name||'To be determined';
const player=id=>data.Players.find(p=>p.id===id)?.name||'Player TBD';
const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'}):'Date TBD';
const teamTone=id=>{const ids=[...data.Teams].map(t=>String(t.id)).sort();return Math.max(0,ids.indexOf(String(id)))%4;};
const team=id=>`<span class="team team-tone-${teamTone(id)}"><span class="crest">${esc(id||'?')}</span>${esc(name(id))}</span>`;
const formatName=f=>f==='SINGLES'?'Net singles match play':f==='SCRAMBLE'?'4-person gross scramble':f==='STABLEFORD'?'Net Stableford':'Best-ball match play';
const avg=a=>a.length?(a.reduce((x,y)=>x+y,0)/a.length).toFixed(1):'—';
const heading=(title,sub,extra='')=>`<div class="section-head"><div><h2>${title}</h2><p class="sub">${sub}</p></div>${extra}</div>`;
function renderNews(){
 const box=$('league-news');if(!box)return;
 const yes=v=>v===true||String(v).trim().toLowerCase()==='true';
 const stamp=v=>/^\d{4}-\d{2}-\d{2}$/.test(String(v))&&Number.isFinite(Date.parse(v+'T12:00:00'))?String(v):'';
 const posts=(data.News||[]).filter(r=>yes(r.published)&&String(r.headline||'').trim()).map((r,i)=>({...r,order:i,day:stamp(r.date)})).sort((a,b)=>Number(yes(b.pinned))-Number(yes(a.pinned))||b.day.localeCompare(a.day)||b.order-a.order);
 box.hidden=!posts.length;if(!posts.length){box.innerHTML='';return;}
 const card=p=>`<article class="news-post"><div class="news-meta">${yes(p.pinned)?'<span class="badge">Pinned</span>':''}${p.day?`<time datetime="${esc(p.day)}">${esc(new Date(p.day+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}))}</time>`:''}</div><h3>${esc(p.headline)}</h3><p class="news-message">${esc(p.message)}</p></article>`;
 box.innerHTML=`<details class="news-digest"><summary><span class="news-kicker">League news</span><span class="news-preview">${esc(posts[0].headline)}</span><span class="news-expand">Read updates ↓</span></summary>${card(posts[0])}${posts.length>1?`<details class="news-older"><summary>View older updates (${posts.length-1})</summary>${posts.slice(1).map(card).join('')}</details>`:''}</details>`;
}
function bannerContent(){
 const w=data.Weeks.find(w=>Number(w.week)===week);if(!w)return '';
 const key=v=>String(v||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
 const published=(data.Courses||[]).filter(c=>c.published===true||String(c.published).toLowerCase()==='true');
 const assigned=published.filter(c=>Number(c.week)===week);
 const hasCourse=String(w.course||'').trim()&&!/^(tbd|course tbd|to be determined)$/i.test(String(w.course).trim());
 const profile=hasCourse?published.find(c=>key(c.name)===key(w.course)):(assigned.length===1?assigned[0]:null);
 const title=hasCourse?w.course:profile?.name||'Course to be announced';
 const media=(window.LEAGUE_COURSE_MEDIA||[]).find(m=>[m.name,...(m.aliases||[])].some(n=>key(n)===key(title)));
 let photo='',source='';try{if(media&&new URL(media.photo).protocol==='https:')photo=media.photo;if(media&&new URL(media.source).protocol==='https:')source=media.source;}catch{}
 return `${photo?`<img class="banner-photo" src="${esc(photo)}" alt="${esc(title)}" decoding="async" referrerpolicy="no-referrer">`:''}<div class="banner-copy"><p class="eyebrow">${week===upcomingWeek()?'Up next':'Selected week'} · Week ${week}</p><h2>${esc(title)}</h2><p>${esc(formatName(w.format||'BEST_BALL'))} · ${date(w.wed)} & ${date(w.sat)}</p></div>${photo&&source?`<a class="banner-credit" href="${esc(source)}" target="_blank" rel="noopener noreferrer">Photo: ${esc(media.credit)}</a>`:''}`;
}
function fullMatchDate(value){return value?new Date(value+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}):'Date to be confirmed';}
function weekControls(){const weeks=[...data.Weeks].sort((a,b)=>a.week-b.week),i=weeks.findIndex(w=>+w.week===week);return `<div class="week-controls compact-week" aria-label="Choose your playing week"><button id="previous-week" ${i<=0?'disabled':''} aria-label="Previous week">‹</button><label for="week" class="sr-only">Choose a week</label><select id="week">${weeks.map(w=>`<option value="${w.week}" ${+w.week===week?'selected':''}>Week ${w.week} · ${date(w.wed)} & ${date(w.sat)}</option>`).join('')}</select><button id="next-week" ${i===weeks.length-1?'disabled':''} aria-label="Next week">›</button>${week!==upcomingWeek()?'<button id="current-week" class="current-week">Current week</button>':''}</div>`;}
function nextPlayerMatch(selected,now=new Date()){
 if(!selected)return null;
 const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now),part=k=>parts.find(p=>p.type===k).value,today=part('year')+'-'+part('month')+'-'+part('day'),minutes=+part('hour')*60+ +part('minute');
 const candidates=data.Weeks.flatMap(w=>{const cards=w.format==='SCRAMBLE'?(data.Scramble||[]).filter(r=>+r.week===+w.week&&r.team===selected.team):data.Matches.filter(m=>+m.week===+w.week&&data.Rounds.some(r=>r.match===m.id&&r.player===selected.id));return cards.map(m=>({w,m,time:w.format==='SCRAMBLE'?m.time:matchTime(m,w)}));}).filter(x=>x.m.date&&(x.m.date>today||x.m.date===today&&(clockMinutes(x.time)===null||clockMinutes(x.time)>=minutes)));
 candidates.sort((a,b)=>a.m.date.localeCompare(b.m.date)||(clockMinutes(a.time)??1440)-(clockMinutes(b.time)??1440));return candidates[0]||null;
}
function playerIdentity(selected){return selected?`<div class="player-identity"><div><span>Showing schedule for</span><strong>${esc(selected.name)}</strong><small>Check the name — this browser remembers the last player selected.</small></div><button id="change-player">Change player</button></div>`:'';}
function personalMatchSummary(selected,w,matchId=null){
 if(!selected)return '';
 const cards=w.format==='SCRAMBLE'?(data.Scramble||[]).filter(r=>+r.week===+w.week&&r.team===selected.team):data.Matches.filter(m=>+m.week===+w.week&&data.Rounds.some(r=>r.match===m.id&&r.player===selected.id));
 if(!cards.length)return '<div class="personal-match-summary notice-info">No assignment yet for this week.</div>';
 return cards.filter(m=>matchId===null||m.id===matchId).map(m=>{const rows=data.Rounds.filter(r=>r.match===m.id),own=rows.find(r=>r.player===selected.id);const names=rr=>rr.map(r=>esc(player(r.player))).join(' + ')||'To be confirmed';const detail=w.format==='SCRAMBLE'?`Team: ${data.Players.filter(p=>p.team===selected.team).map(p=>esc(p.name)).join(' + ')}`:`${rows.some(r=>r.side===own.side&&r.player!==selected.id)?'Partner: '+names(rows.filter(r=>r.side===own.side&&r.player!==selected.id))+' · ':''}Opponents: ${names(rows.filter(r=>r.side!==own.side))}`;return `<div class="personal-match-summary"><strong>${esc(selected.name)} plays ${esc(fullMatchDate(m.date))} · ${esc(w.format==='SCRAMBLE'?m.time||'Time TBD':matchTime(m,w))}</strong><span>${detail}</span></div>`;}).join('');
}
function matchFinder(){const selected=data.Players.find(p=>p.id===schedulePlayer),next=nextPlayerMatch(selected);return `<section class="match-finder next-match ${selected?'':'next-match-empty'}"><div class="next-match-title">${selected?'<h2>Your next match</h2>':''}<label for="find-player">${selected?'Player':'Your next match'}</label><select id="find-player"><option value="">Choose your name</option>${[...data.Players].sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<option value="${esc(p.id)}" ${p.id===schedulePlayer?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>${selected?`${playerIdentity(selected)}${next?personalMatchSummary(selected,next.w,next.m.id??null)+`<a href="#schedule/${next.w.week}">View week ${next.w.week} →</a>`:'<p class="notice notice-info">No upcoming dated match assigned. Check My schedule for pending assignments.</p>'}<a href="#my-schedule">My full season →</a>`:''}</section>`;}
function courseMedia(c){
 const key=v=>String(v||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
 const entry=(window.LEAGUE_COURSE_MEDIA||[]).find(m=>[m.name,...(m.aliases||[])].some(n=>key(n)===key(c.name)));if(!entry)return '';
 const safe=v=>{try{const u=new URL(v);return u.protocol==='https:'?u.href:'';}catch{return '';}};
 const photo=safe(entry.photo),logo=safe(entry.logo),source=safe(entry.source);
 return `${photo?`<figure class="course-photo"><img src="${esc(photo)}" alt="${esc(c.name)}${c.name==='The Old Game'?' GSPro showcase':' course view'}" loading="lazy" decoding="async" referrerpolicy="no-referrer"><figcaption>${source?`<a href="${esc(source)}" target="_blank" rel="noopener noreferrer">${esc(entry.credit||'Image source')}</a>`:esc(entry.credit||'')}</figcaption></figure>`:''}${logo?`<div class="course-logo ${entry.darkLogo?'course-logo-dark':''}"><img src="${esc(logo)}" alt="${esc(entry.logoLabel||c.name+' logo')}" loading="lazy" decoding="async" referrerpolicy="no-referrer"></div>`:''}`;
}
function courses(){
 const yes=v=>v===true||String(v).trim().toLowerCase()==='true';
 const weekNumber=v=>String(v??'').trim()!==''&&Number.isInteger(Number(v))&&Number(v)>=1&&Number(v)<=12?Number(v):null;
 const rows=(data.Courses||[]).filter(c=>yes(c.published)&&String(c.name||'').trim()).sort((a,b)=>(weekNumber(a.week)??99)-(weekNumber(b.week)??99)||String(a.name).localeCompare(String(b.name)));
 const link=v=>{try{const u=new URL(String(v));return u.protocol==='https:'||u.protocol==='http:'?`<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">Course website ↗</a>`:'';}catch{return '';}};
 const text=v=>String(v??'').trim();
 return heading('Our courses','From mountain fairways and Scottish-inspired links to some of golf’s most recognizable championship venues, our course selection brings a different challenge to every league round. Explore the layouts, learn what makes each one special, and find your next favorite.')+`<p class="note">Real-world course details are provided for background. League tees, yardages, and playing conditions are determined by the selected GSPro version and event setup.</p>`+(rows.length?`<div class="course-list">${rows.map(c=>`<article class="card course-entry">${courseMedia(c)}<span class="badge">${weekNumber(c.week)?'Week '+weekNumber(c.week):'Week to be confirmed'}</span><h3>${esc(c.name)}</h3>${text(c.location)?`<p class="sub">${esc(c.location)}</p>`:''}${text(c.description)?`<p class="course-description">${esc(c.description)}</p>`:''}<dl>${[['Designer',c.designer],['Opened',c.yearOpened],['Nine holes',c.nine],['Tees',c.tees]].filter(([,v])=>text(v)).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${link(c.website)}</article>`).join('')}</div>`:'<div class="notice notice-info">Our course lineup is still taking shape. Check back for course details as selections are announced.</div>');
}
function teams(){
 return heading('Meet the teams','The league roster, team by team.')+`<div class="grid">${data.Teams.map(t=>{const roster=data.Players.filter(p=>p.team===t.id);return `<section class="card"><h3>${team(t.id)}</h3><ul>${roster.map(p=>`<li>${esc(p.name)}</li>`).join('')||'<li>Roster to be announced</li>'}</ul></section>`;}).join('')}</div><p class="note">Rosters reflect the team assignments in Players. Substitute appearances on individual scorecards do not change these rosters.</p>`;
}
function standings(){return heading('The race to the playoffs','Regular season · 2 points for a pair win · 1 for a tie','<span class="badge">4 POINTS AVAILABLE PER TEAM / WEEK</span>')+`<div class="table-wrap"><table class="standings-table"><thead><tr><th>Rank</th><th>Team</th><th>Points</th><th>Pairs played</th><th>W</th><th>T</th><th>L</th><th>Holes won</th><th>Scramble pts</th></tr></thead><tbody>${model.table.map((t,i)=>`<tr class="${i===0&&!model.table.some(t=>t.unresolved)?'standings-leader':''}"><td>${i+1}${t.unresolved?'*':''}</td><td>${team(t.id)}</td><td class="points">${t.points}</td><td>${t.played}</td><td>${t.w}</td><td>${t.d}</td><td>${t.l}</td><td>${t.holes}</td><td>${t.scramblePoints??'—'}</td></tr>`).join('')}</tbody></table></div><p class="note">Tiebreaks: head-to-head points among tied teams, then holes won across all nine holes in both formats, then admin decision. ${model.table.some(t=>t.unresolved)?'* Provisional display order: some teams remain tied; this is not a final seed.':''} Playoff seeds lock after all ${model.pairWeeks*4} regular-season pair matches${model.scrambles.length?' and the scramble':''} are complete and ties are resolved.</p>`;}
function golfScore(score,par){
 if(score===null||score===undefined||String(score).trim()==='')return '';
 const value=Number(score),holePar=Number(par);
 if(!Number.isFinite(value)||!Number.isFinite(holePar)||holePar<=0)return esc(score);
 const diff=value-holePar,kind=diff<=-2?'eagle':diff===-1?'birdie':diff===0?'par':diff===1?'bogey':'double-bogey';
 const label=`${score} strokes, ${diff===0?'par':Math.abs(diff)+' '+(diff<0?'under':'over')+' par'}`;
 return `<span class="golf-score ${kind}" title="${esc(label)}"><span aria-hidden="true">${esc(score)}</span><span class="sr-only">${esc(label)}</span></span>`;
}
// Hole remains the score-entry slot (h1…h9); courseHole is a display label only.
function courseHoleLabel(week,slot){const h=data.Holes.find(h=>+h.week===+week&&+h.hole===+slot);return h&&String(h.courseHole??'').trim()!==''?h.courseHole:slot;}
function scorecardSetup(p){
 const holes=(p.holes||data.Holes.filter(h=>+h.week===+p.match.week)).slice().sort((a,b)=>a.hole-b.hole);
 if(holes.length!==9||holes.some((h,i)=>+h.hole!==i+1||!Number.isInteger(+h.par)||+h.par<1||!Number.isInteger(+h.rank)||+h.rank<1||+h.rank>9)||new Set(holes.map(h=>+h.rank)).size!==9)return {error:'Scorecard pending: enter nine pars and unique stroke ranks 1–9.'};
 const labeled=holes.filter(h=>String(h.courseHole??'').trim()!=='');
 if(labeled.length&&(labeled.length!==9||holes.some((h,i)=>!Number.isInteger(+h.courseHole)||+h.courseHole<1||+h.courseHole>18||(i>0&&+h.courseHole<=+holes[i-1].courseHole))))return {error:'Scorecard setup needs attention: enter all nine courseHole numbers, in ascending order, from 1–18.'};
 if(p.complete)return {...p,holes,label:matchResultLabel(p.label)};
 // Use the existing engine's validation and stroke allocation without publishing
 // fabricated results: placeholder scores are discarded immediately below.
 const rows=data.Rounds.filter(r=>r.match===p.id);
 const fixture=model.fixtures.find(f=>f.pairs.some(pair=>pair.id===p.id));
 const teams=p.teams||fixture?.teams||[];
 const probe=League.pair({...data,Rounds:data.Rounds.map(r=>r.match===p.id?{...r,...Object.fromEntries(holes.map(h=>['h'+h.hole,4]))}:r)},p.match,teams);
 const rounds=rows.map(r=>{const allocated=probe.complete?probe.rounds.find(x=>x.player===r.player):null;const gross=holes.map(h=>{const v=r['h'+h.hole];return String(v??'').trim()!==''&&Number.isInteger(+v)&&+v>=1&&+v<=30?+v:'';});return {...r,shots:allocated?allocated.shots:null,gross,grossTotal:gross.every(v=>v!=='')?gross.reduce((a,b)=>a+b,0):''};});
 return {...p,holes,rounds,teams,allocationPending:!probe.complete,allocationMessage:probe.message};
}
function strokeDots(shots,rank){
 if(shots===null||shots===undefined)return '';
 const count=League.strokes(shots,+rank);if(!count)return '';
 const label=Math.abs(count)+' stroke'+(Math.abs(count)===1?'':'s')+(count>0?' received':' given back');
 return `<span class="stroke-dots" title="${esc(label)}"><span aria-hidden="true">${count>0?'•'.repeat(count):'−'.repeat(-count)}</span><span class="sr-only">${esc(label)}</span></span>`;
}
function scorecardRows(p,teamRows=[]){
 const row=(label,values,total='')=>`<tr><td>${label}</td>${values.map(v=>`<td>${esc(v)}</td>`).join('')}<td>${esc(total)}</td></tr>`;
 const rounds=[...p.rounds].sort((a,b)=>a.side.localeCompare(b.side));
 return row('Par',p.holes.map(h=>h.par),p.holes.reduce((n,h)=>n+Number(h.par),0))+row('Handicap',p.holes.map(h=>h.rank))+rounds.map((r,index)=>`<tr><td>${esc(player(r.player))} (${r.shots===null?'pending':esc(r.shots)})</td>${r.gross.map((v,i)=>`<td class="score-hole"><span class="score-cell-content">${golfScore(v,p.holes[i].par)}${strokeDots(r.shots,p.holes[i].rank)}</span></td>`).join('')}<td>${esc(r.grossTotal)}</td></tr>${rounds[index+1]?.side!==r.side?(teamRows[r.side==='A'?0:1]||''):''}`).join('');
}
function scorecardLegend(){return '<p class="scorecard-legend">Dots in the upper-right show strokes received on that hole; a minus sign means a stroke given back. Gross score symbols: circle = birdie; double circle = eagle or better; square = bogey; double square = double bogey or worse.</p>';}
function scorecardTable(p,footer){return mobileScorecard(p)+`<div class="table-wrap desktop-scorecard"><table class="scorecard"><thead><tr><th>Player / gross</th>${p.holes.map(h=>`<th>${esc(h.courseHole||h.hole)}</th>`).join('')}<th>Total</th></tr></thead><tbody>${scorecardRows(p,p.format==='STABLEFORD'?[stablefordTeamRow(p,0),stablefordTeamRow(p,1)]:[])}${p.format==='STABLEFORD'?'':footer}</tbody></table></div>`;}
function stablefordTeamRow(p,side){
 const rows=p.rounds.filter(r=>r.side===(side===0?'A':'B'));
 const values=p.complete?(side===0?p.a:p.b):p.holes.map((h,i)=>!p.allocationPending&&rows.length===2&&rows.every(r=>Number.isInteger(r.gross[i])&&r.gross[i]>0&&Number.isFinite(r.shots))?rows.reduce((sum,r)=>sum+League.stableford(r.gross[i]-League.strokes(r.shots,+h.rank),+h.par),0):null);
 const played=values.filter(v=>v!==null),total=p.complete?p.totals[side]:played.length?played.reduce((a,b)=>a+b,0):'—';
 return `<tr class="scorecard-summary"><td>${esc(name(p.teams[side]))}</td>${values.map(v=>`<td>${v===null?'—':esc(v)}</td>`).join('')}<td>${esc(total)}</td></tr>`;
}
function liveScorecardSummary(p){
 const sides=['A','B'].map(side=>p.rounds.filter(r=>r.side===side));
 const size=p.format==='SINGLES'?1:2;
 const ready=(rows,i)=>!p.allocationPending&&rows.length===size&&rows.every(r=>Number.isInteger(r.gross[i])&&r.gross[i]>0&&Number.isFinite(r.shots));
 if(p.format==='STABLEFORD')return [0,1].map(side=>stablefordTeamRow(p,side)).join('');
 let lead=0,continuous=true,count=0;
 const values=p.holes.map((h,i)=>{if(!continuous||!sides.every(rows=>ready(rows,i))){continuous=false;return '—';}const net=sides.map(rows=>Math.min(...rows.map(r=>r.gross[i]-League.strokes(r.shots,+h.rank))));lead+=net[0]<net[1]?1:net[0]>net[1]?-1:0;count++;return lead>0?lead+'UP':lead<0?Math.abs(lead)+'DN':'AS';});
 const cell=v=>`<td class="${v==='—'?'':'match-'+(v.endsWith('UP')?'up':v.endsWith('DN')?'down':'square')}">${v}</td>`;
 return `<tr class="scorecard-summary"><td>Match</td>${values.map(cell).join('')}<td>${count?values[count-1]+' (through '+count+')':'—'}</td></tr>`;
}
function scorecard(p){
 p=scorecardSetup(p);if(p.error)return `<p class="notice notice-info">${esc(p.error)}</p>`;
 if(p.complete&&p.format==='STABLEFORD')return stablefordCard(p);
 if(!p.complete)return `<p class="notice notice-info">${p.allocationPending?'Stroke allocations pending: '+esc(p.allocationMessage||'save the match handicaps first')+'.':'Pre-match / in-progress scorecard. Stroke dots use the saved match handicaps.'} No points awarded until all scorecards are complete.</p>`+scorecardTable(p,liveScorecardSummary(p))+scorecardLegend()+`<p>Parentheses show ${p.format==='STABLEFORD'?'the full allowance-adjusted handicap':'strokes off the lowest allowance-adjusted handicap in this match'}. Handicap lists the manually assigned stroke ranks 1–9.</p><p>${p.format==='STABLEFORD'?'Team rows show combined net Stableford points for each individual hole; Total adds the completed holes so far.':'Match shows the running result from '+esc(name(p.teams[0]))+'’s perspective: UP = ahead, DN = behind, AS = all square. It updates through consecutive completed holes.'} Unscored holes remain blank (—); results are provisional until all scores are entered.</p>`;
 let lead=0;const running=p.wins.map(win=>{lead+=win;return lead>0?lead+'UP':lead<0?Math.abs(lead)+'DN':'AS';});
 const matchRow=`<tr class="scorecard-summary"><td>Match</td>${running.map(v=>`<td class="match-${v.endsWith('UP')?'up':v.endsWith('DN')?'down':'square'}">${v}</td>`).join('')}<td class="match-${p.winner==='A'?'up':p.winner==='B'?'down':'square'}">${esc(p.label)}</td></tr>`;
 return `<p>${esc(p.winner?name(p.teams[p.winner==='A'?0:1])+' wins '+p.label:'Match tied')} · Allowance ${esc(p.match.allowance)}%</p>`+scorecardTable(p,matchRow)+scorecardLegend()+`<p>Strokes in parentheses = adjusted handicap minus the lowest adjusted handicap in this ${p.format==='SINGLES'?'singles match':'foursome'}. Handicap lists each hole’s stroke rank.</p><p>Match is shown from ${esc(name(p.teams[0]))}’s perspective (the first ${p.format==='SINGLES'?'player':'pair'} listed): UP = ahead, DN = behind, AS = all square. The row tracks all nine holes; the official result in Total locks when a lead exceeds the holes remaining.</p>`;
}
function stablefordCard(p){
 return scorecardTable(p,'')+scorecardLegend()+`<p>Player rows show gross scores. Strokes in parentheses are each player’s full allowance-adjusted handicap for Stableford. Handicap lists each hole’s stroke rank. Team total rows add both players’ net Stableford points on each hole; the higher nine-hole points total wins. Allowance ${esc(p.match.allowance)}%.</p>`;
}
function fixtureCard(f){return `<article class="card ${f.winner&&+f.week===12?'winner':''}"><div class="card-top"><span>${esc(f.id)} · ${f.complete?'Complete':'Scheduled / in progress'}</span><span>${+f.week<=10?'Team matchup':'Playoff'}</span></div><div class="match-line">${team(f.teams[0])}<strong>${f.pairs.some(p=>p.complete)?f.points[0]:'—'}</strong></div><div class="match-line">${team(f.teams[1])}<strong>${f.pairs.some(p=>p.complete)?f.points[1]:'—'}</strong></div>${f.pairs.map(p=>{const rr=data.Rounds.filter(r=>r.match===p.id);return `<details class="pair" open><summary>${date(p.match.date)} · ${esc(formatName(p.format))} · ${esc(p.id)} · ${p.complete?p.points.join(' – '):'Awaiting scores'}</summary><p>A: ${rr.filter(r=>r.side==='A').map(r=>esc(player(r.player))).join(' + ')}<br>B: ${rr.filter(r=>r.side==='B').map(r=>esc(player(r.player))).join(' + ')}</p>${scorecard(p)}</details>`;}).join('')}${+f.week>10&&f.complete&&f.points[0]===f.points[1]?`<p class="note">${f.winner?'Playoff winner: '+esc(name(f.winner))+' · '+esc(f.playoff.note):'Team points tied. Awaiting the winner of an admin-determined playoff.'}</p>`:''}</article>`;}
let schedulePlayer='';try{schedulePlayer=localStorage.getItem('league-selected-player')||'';}catch{}
function rememberPlayer(value){schedulePlayer=value;try{localStorage.setItem('league-selected-player',value);}catch{}}
function clockMinutes(value){
 const v=String(value??'').trim(),t=v.match(/^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)$/i),mil=v.match(/^(\d{1,2}):(\d{2})$/);
 if(t&&+t[1]>=1&&+t[1]<=12&&+(t[2]||0)<60)return (+t[1]%12+(t[3].toUpperCase()==='PM'?12:0))*60+ +(t[2]||0);
 if(mil&&+mil[1]<24&&+mil[2]<60)return +mil[1]*60+ +mil[2];
 return null;
}
function matchTime(m,w){
 if(String(m.time??'').trim()){const minutes=clockMinutes(m.time);if(minutes===null)return 'Check time';const hour=Math.floor(minutes/60);return (hour%12||12)+':'+String(minutes%60).padStart(2,'0')+' '+(hour>=12?'PM':'AM');}

 // Pair-match IDs W1A-1/W1A1 and W1B-2/W1B2 use slots 1 and 2.
 const slot=String(m.id).match(/A-?([12])$|B-?([12])$/i);
 if(!slot)return 'Time TBD';const early=Number(slot[1]||slot[2])===1;
 return m.date===w.wed?(early?'5:00 PM':'7:30 PM'):m.date===w.sat?(early?'11:00 AM':'1:30 PM'):'Time TBD';
}
function playerSchedule(){
 const selected=data.Players.find(p=>p.id===schedulePlayer);
 const selector=`<label>Player <select id="schedule-player"><option value="">Choose a player</option>${[...data.Players].sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<option value="${esc(p.id)}" ${p.id===schedulePlayer?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`;
 let body='';
 if(selected){body=`<div class="table-wrap personal-schedule"><table><thead><tr><th>Week</th><th>Date</th><th>Time</th><th>Your pair / team</th><th>Opponents</th><th>Course / format</th></tr></thead><tbody>${[...data.Weeks].sort((a,b)=>a.week-b.week).map(w=>{
  const label=`${esc(w.course||'Course TBD')}<br><small>${esc(formatName(w.format||'BEST_BALL'))}</small>`;
  const day=v=>v?esc(new Date(v+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})):'Date TBD';
  if(w.format==='SCRAMBLE'){const card=(data.Scramble||[]).find(r=>Number(r.week)===Number(w.week)&&r.team===selected.team);return `<tr><td>${w.week}</td><td>${day(card?.date)}</td><td>${esc(card?.time||'Time TBD')}</td><td>${data.Players.filter(p=>p.team===selected.team&&selected.team).map(p=>esc(p.name)).join(' + ')||'TBD'}</td><td>All other teams</td><td>${label}</td></tr>`;}
  const matches=data.Matches.filter(m=>Number(m.week)===Number(w.week)&&data.Rounds.some(r=>r.match===m.id&&r.player===selected.id));
  if(!matches.length)return `<tr><td>${w.week}</td><td>Date TBD</td><td>Time TBD</td><td>${Number(w.week)>10?'Playoff assignment pending':'Not assigned yet'}</td><td>To be confirmed</td><td>${label}</td></tr>`;
  return matches.map(m=>{const rows=data.Rounds.filter(r=>r.match===m.id),own=rows.find(r=>r.player===selected.id);const names=rr=>rr.map(r=>esc(player(r.player))).join(' + ')||'TBD';return `<tr><td>${w.week}</td><td>${day(m.date)}</td><td>${matchTime(m,w)}</td><td>${(m.format||w.format)==='SINGLES'?esc(selected.name):names(rows.filter(r=>r.side===own.side))}</td><td>${names(rows.filter(r=>r.side!==own.side))}</td><td>${esc(w.course||'Course TBD')}<br><small>${esc(formatName(m.format||w.format||'BEST_BALL'))}</small></td></tr>`;}).join('');
 }).join('')}</tbody></table></div><p class="note">Times are local league times. Pair match 1 uses the early slot; pair match 2 uses the late slot, based on its assigned Wednesday or Saturday date. An entered Matches time overrides the default, including for playoffs. Scramble times come from the team card; blank playoff times remain TBD. Scramble teammates reflect the current team roster. Assignments can change.</p>`;}else body='<div class="notice notice-info">Choose your name to see your full season on one page.</div>';
 return heading('My season schedule',selected?esc(selected.name)+' · All 12 weeks':'Dates, times, partners and opponents.',selector)+playerIdentity(selected)+body;
}
function schedule(){
 const w=data.Weeks.find(w=>+w.week===week);
 const selected=data.Players.find(p=>p.id===schedulePlayer);const header=matchFinder()+`<section id="week-banner" class="week-banner${bannerContent().includes('class="banner-photo"')?'':' week-banner-compact'}" aria-label="Selected week’s course">${bannerContent()}</section>`+heading('Schedule & results',`Week ${week} · ${date(w.wed)} & ${date(w.sat)} · ${formatName(w.format||'BEST_BALL')}`,weekControls())+(selected?`<div class="selected-week-match"><h3>${esc(selected.name)} · Selected week ${week}</h3>${personalMatchSummary(selected,w)}</div>`:'');
 const fixtures=model.fixtures.filter(f=>+f.week===week),pairs=fixtures.flatMap(f=>f.pairs.map(p=>({...p,teams:p.teams||f.teams||[null,null]})));
 const teamSummary=w.format==='SCRAMBLE'?'':`<section class="weekly-opponents" aria-label="This week’s team matchups"><h3>This week’s team matchups</h3><div>${fixtures.map(f=>`<p><strong class="team-label team-tone-${teamTone(f.teams[0])}">${esc(name(f.teams[0]))}</strong><span> vs </span><strong class="team-label team-tone-${teamTone(f.teams[1])}">${esc(name(f.teams[1]))}</strong></p>`).join('')}</div></section>`;
 const longDate=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}):'Date to be confirmed';
 const matchCard=p=>{const rows=data.Rounds.filter(r=>r.match===p.id),live=matchLiveTotals(p);return `<article class="schedule-match" ${rows.some(r=>r.player===schedulePlayer)?'data-my-match="true"':''}><div class="schedule-match-top">${rows.some(r=>r.player===schedulePlayer)?'<span class="my-match-label">Your match</span>':''}<strong>${matchTime(p.match,w)}</strong><span class="badge ${p.complete?'badge-final':'badge-pending'}">${p.complete?(p.winner?'Final':'Final · Tied'):live.decided?'Decided · '+live.label:live.played?'Live · Through '+live.played:'Scheduled'}</span></div><div class="schedule-opponents">${['A','B'].map((side,i)=>`${i?'<span class="schedule-versus">vs</span>':''}<div class="schedule-side ${p.complete&&p.winner===side?'schedule-side-winner':''}"><span class="schedule-team team-label team-tone-${teamTone(p.teams[i])}">${esc(name(p.teams[i]))}</span><div class="duo-score"><p class="schedule-names">${rows.filter(r=>r.side===side).map(r=>esc(player(r.player))).join(' + ')||'Players to be confirmed'}</p><strong class="duo-points" aria-label="${p.format==='STABLEFORD'?'Stableford points':'Match standing'}">${esc(live.values[i])}</strong></div>${p.complete&&p.winner===side?'<span class="winner-tag">✓ Winner</span>':''}</div>`).join('')}</div><div class="scorer-action" data-match="${esc(p.id)}"></div><details class="schedule-scorecard" data-card="${esc(p.id)}"><summary>Scorecard</summary>${scorecard(p)}</details></article>`;};
 const scramble=w.format==='SCRAMBLE';
 const cards=scramble?(data.Scramble||[]).filter(r=>+r.week===week):pairs;
 const assignedDate=c=>scramble?c.date:c.match.date;
 const timeOrder=c=>clockMinutes(scramble?c.time:matchTime(c.match,w))??9999;
 const card=c=>scramble?`<article class="schedule-match" ${data.Players.some(p=>p.id===schedulePlayer&&p.team===c.team)?'data-my-match="true"':''}><div class="schedule-match-top"><strong>${esc(c.time||'Time TBD')}</strong><span class="badge">Team scramble</span></div><span class="schedule-team team-label team-tone-${teamTone(c.team)}">${esc(name(c.team))}</span><p class="schedule-names">${data.Players.filter(p=>p.team===c.team).map(p=>esc(p.name)).join(' + ')||'Players to be confirmed'}</p></article>`:matchCard(c);
 const dates=[w.wed,w.sat,...new Set(cards.map(assignedDate).filter(d=>d&&d!==w.wed&&d!==w.sat))];
 const dayBlock=(title,items)=>`<section class="schedule-day"><h3>${esc(title)}</h3>${items.sort((a,b)=>timeOrder(a)-timeOrder(b)).map(card).join('')||'<p class="schedule-empty notice notice-info">Match assignments to be confirmed.</p>'}</section>`;
 const undated=cards.filter(c=>!assignedDate(c));
 return header+teamSummary+`<p class="schedule-help">Find your day and start time below. All times are local league times.</p><div class="schedule-days">${dates.map(d=>dayBlock(longDate(d),cards.filter(c=>assignedDate(c)===d))).join('')}${undated.length?dayBlock('Date to be confirmed',undated):''}</div>`+(scramble?`<section class="schedule-scramble-results"><h3>Scramble results</h3>${scrambleCard(w)}</section>`:'');
}
function scrambleCard(w){const result=model.scrambles.find(s=>s.week===+w.week);const rows=result.complete?result.rows:(data.Scramble||[]).filter(r=>+r.week===+w.week);return `<div class="notice">One gross score per team · No handicaps · 4 / 3 / 2 / 1 standings points. ${result.complete?'Final results':'Provisional: no points until all four scorecards and stroke ranks are complete.'}</div>${!result.complete?`<p class="sub">${esc(result.message)}</p>`:''}<div class="table-wrap"><table class="scorecard"><thead><tr><th>Team</th><th>Date</th><th>Time</th><th>Place</th>${Array.from({length:9},(_,i)=>`<th>H${i+1}</th>`).join('')}<th>Gross</th><th>League pts</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${team(r.team)}</td><td>${date(r.date)}</td><td>${esc(r.time||'Time TBD')}</td><td>${result.complete?(r.shared?'T':'')+r.place:'—'}</td>${Array.from({length:9},(_,i)=>`<td>${r['h'+(i+1)]===''||r['h'+(i+1)]==null?'—':esc(r['h'+(i+1)])}</td>`).join('')}<td>${result.complete?r.total:'—'}</td><td>${result.complete?r.points:'—'}</td></tr>`).join('')}</tbody></table></div><p class="note">Lowest gross total wins. Ties compare gross scores at stroke ranks 1, 2, …, 9, hardest first. ${result.complete?'Comparison hole order: '+result.order.join(' → ')+'. ':''}Only identical scorecards share the average points for their occupied places. Scramble scores do not enter individual statistics, head-to-head results, or holes-won tiebreak totals.</p>`;}
function players(){const rows=model.stats.map(p=>{const rr=p.rounds.filter(r=>statScope==='all'||(statScope==='regular'?r.week<=10:r.week>10));return {...p,rr,gross:rr.length?rr.reduce((s,r)=>s+r.grossTotal,0)/rr.length:Infinity,net:rr.length?rr.reduce((s,r)=>s+r.netTotal,0)/rr.length:Infinity};}).sort((a,b)=>a[sortBy]-b[sortBy]||a.name.localeCompare(b.name));return heading('Every stroke counts','Complete 9-hole rounds · Gross and handicap-adjusted performance')+`<div class="toolbar"><label>Rounds <select id="scope"><option value="regular" ${statScope==='regular'?'selected':''}>Regular season</option><option value="playoffs" ${statScope==='playoffs'?'selected':''}>Playoffs</option><option value="all" ${statScope==='all'?'selected':''}>Full season</option></select></label><label>Sort by <select id="sort"><option value="gross" ${sortBy==='gross'?'selected':''}>Gross average</option><option value="net" ${sortBy==='net'?'selected':''}>Net average</option></select></label></div><p class="note">Individual net = gross total minus the full adjusted 9-hole handicap, before shots off the low player. No minimum-round qualification. Scramble rounds are excluded.</p><div class="table-wrap"><table class="player-stats-table"><thead><tr><th>Player</th><th>Rounds</th><th>Gross avg</th><th>Net avg</th><th>Best gross</th><th>Best net</th><th>Pars</th><th>Birdies</th><th>Eagles+</th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong><br><small>${esc(name(p.team))}</small></td><td>${p.rr.length}</td><td>${avg(p.rr.map(r=>r.grossTotal))}</td><td>${avg(p.rr.map(r=>r.netTotal))}</td><td>${p.rr.length?Math.min(...p.rr.map(r=>r.grossTotal)):'—'}</td><td>${p.rr.length?Math.min(...p.rr.map(r=>r.netTotal)):'—'}</td><td>${p.rr.reduce((s,r)=>s+r.pars,0)}</td><td>${p.rr.reduce((s,r)=>s+r.birdies,0)}</td><td>${p.rr.reduce((s,r)=>s+r.eagles,0)}</td></tr>`).join('')}</tbody></table></div>`;}
function tentativeSemifinal(f){
 const seed=token=>/^S[1-4]$/.test(String(token))?Number(token.slice(1)):null;
 const sides=[f.teamA,f.teamB].map(token=>{const rank=seed(token);return {rank,t:rank?model.table[rank-1]:null};});
 const started=model.table.some(t=>t.played>0)||model.scrambles.some(s=>s.complete);
 return `<article class="card"><div class="card-top"><span>${esc(f.id)}</span><span>Tentative matchup</span></div>${sides.map(({rank,t})=>`<div class="match-line"><div><small>Seed ${rank??'TBD'}</small>${started&&t?team(t.id):'<p>To be determined</p>'}</div><strong>${started&&t?t.points+' pts':'—'}</strong></div>`).join('')}<p class="note">${!started?'Matchups appear once regular-season results are entered.':sides.some(s=>s.t?.unresolved)?'Standings are tied. These pairings use the current display order and may change after the tiebreak is resolved.':'If the season ended with the current standings.'} Final seeds lock only after the regular season and all tiebreaks are complete.</p></article>`;
}
function playoffs(){return heading('The road to the title','All four teams qualify. Four net singles per team matchup · 2 / 1 / 0 points each · maximum 8 per team.')+(!model.seeded?`<div class="notice">${model.regularDone?'Resolve remaining standings ties in Teams → tieOrder to seed the bracket.':'Tentative semifinals update with the standings as results arrive. Final seeds lock after all 10 regular-season weeks and tiebreaks are complete.'}</div>`:'')+`<div class="bracket"><section><p class="eyebrow" style="color:var(--muted)">WEEK 11 · ${weekDates(11)}</p><h3>Semifinals · 1 v 4 / 2 v 3</h3>${model.fixtures.filter(f=>+f.week===11).map(f=>model.seeded?fixtureCard(f):tentativeSemifinal(f)).join('')}</section><section><p class="eyebrow" style="color:var(--muted)">WEEK 12 · ${weekDates(12)}</p><h3>Championship & third place</h3>${model.fixtures.filter(f=>+f.week===12).map(fixtureCard).join('')}</section></div>${teamPrizes()}`;}
function weekDates(n){const w=data.Weeks.find(w=>+w.week===n);return w?`${date(w.wed)} & ${date(w.sat)}`:'Dates to be announced';}
function rules(){const original=rulesContent(),start=original.indexOf('<div class="rules card">'),body=original.slice(start+'<div class="rules card">'.length,-6);const sections=[...body.matchAll(/<h3>(.*?)<\/h3>([\s\S]*?)(?=<h3>|$)/g)].map(m=>`<details class="rule-section"><summary>${m[1]}</summary>${m[2]}</details>`).join('');const c=typeof LeagueExtras==='undefined'?{}:LeagueExtras.config(data),amount=(key,i)=>{const v=c[key+i]===undefined?[80,70,60,50,40][i-1]:Number(c[key+i]);return Number.isFinite(v)&&v>=0?'$'+v.toLocaleString('en-US',{maximumFractionDigits:2}):'Pending';};return heading('How we play','The league in 60 seconds, with the full rules below.')+`<section class="card rules-summary"><h3>League in 60 seconds</h3><ul><li>Four teams of four. Nine holes each week; finish every hole.</li><li>Pair weeks alternate net best ball and net Stableford. Win: 2 points. Tie: 1.</li><li>Week 7 (${weekDates(7)}): four-person gross scramble.</li><li>Singles playoffs: ${weekDates(11)} and ${weekDates(12)}. All teams qualify.</li><li>Weekly net skins: $80 plus carryover. Individual awards count your best qualifying rounds.</li><li>Handicaps are saved before play; the admin manages changes.</li></ul></section><section class="card"><h3>Prize payouts</h3><div class="table-wrap"><table><thead><tr><th>Place</th><th>Low net</th><th>Stableford</th><th>Team prize / player</th></tr></thead><tbody>${[1,2,3,4,5].map((n,i)=>`<tr><td>${n}</td><td>${amount('netPrize',n)}</td><td>${amount('stablefordPrize',n)}</td><td>${i<3?'$'+[100,75,50][i]:'—'}</td></tr>`).join('')}</tbody></table></div><p class="note">Team prizes follow playoff results. No double dipping between individual awards: keep the larger payout; equal payouts go to low net. Ties split occupied prizes.</p></section><div class="rules">${sections}</div>`;}
function rulesContent(){return heading('How we play','The agreed league format, in one place.')+`<div class="rules card"><h3>Four teams. Two pairs per team.</h3><p>On pair-match weeks, admins select two pairs per team and the opposing pairings. Two pair matches play Wednesday and two Saturday. Substitutes are allowed and play under their own player ID and handicap. Everyone completes all nine holes.</p><h3>Net best-ball match play</h3><p>The lower net score of each pair competes hole by hole. Lowest adjusted handicap in each foursome plays off zero; everyone else receives the difference. Strokes fall on ranks 1–9, repeating for handicaps above nine. Each player's handicap is multiplied by the allowance and rounded to the nearest whole stroke (halves away from zero), then differences are taken. Current allowance for newly frozen matches: <strong>${esc(model.settings.allowance)}%</strong>.</p><p>A pair win earns 2 points, a tie 1, and a loss 0. No team bonus; maximum 4 per team per week. A match is decided when a lead exceeds the holes remaining. The remaining holes still count for statistics and the season's net-holes-won tiebreak.</p><h3>Net Stableford weeks</h3><p>Both players earn their own standard net Stableford points on each hole: double bogey or worse 0, bogey 1, par 2, birdie 3, eagle 4, albatross 5, four under par 6. Add both players’ points across all nine holes. Higher pair total earns 2 standings points, a tie 1, a loss 0; maximum 4 per team per week.</p><p>Each player receives their full allowance-adjusted 9-hole handicap, independent of opponents. Stableford matches are decided by the complete nine-hole total, not by holes won. A higher combined Stableford score on a hole counts as a hole won for the season tiebreak. With the week 7 scramble enabled: Stableford in weeks 1, 3, 5, 8, 10; best ball in weeks 2, 4, 6, 9; net singles in both playoff weeks. Each team faces every opponent three times across the nine matchup weeks. Admins can edit each week’s format before freezing matches.</p><h3>Week 7: four-person scramble</h3><p>${weekDates(7)}. Each four-player team submits one nine-hole gross scorecard. Lowest total earns 4 points, then 3, 2, 1. Ties compare individual gross hole scores in stroke-rank order 1–9, hardest first. No handicap strokes are applied. Only scorecards identical through all comparisons split the average points for the places occupied (two tied for first receive 3.5 each). All teams play the same course, tees and simulator settings.</p><p>Enter scores in the Scramble tab, not individual Rounds. Scramble points affect standings but not pair W/T/L, head-to-head, holes won, or player statistics. All four scorecards and valid stroke ranks are required before any scramble points are awarded.</p><h3>Handicaps are subject to change</h3><p>Admins approve the seeded 9-hole handicaps; eligible finalized weeks then calculate bounded updates. Explained overrides remain available. Handicaps, allowance, and format are frozen per match before play; later roster changes do not rewrite existing matches. Plus handicaps are entered as negative numbers.</p><h3>Standings & playoffs</h3><p>Order: points, head-to-head points among teams tied on points, total net holes won, then admin decision. For a multi-team tie, use a mini-table of all games among the tied teams. All teams qualify: 1 v 4 and 2 v 3, then a championship and third-place match.</p><p>Each playoff team matchup has four net singles matches, one per player. The lower adjusted handicap in each singles match plays off zero; the opponent receives the difference. Each singles win earns 2 points, a tie 1 and a loss 0, with 8 points available per team. If the team total is tied 4–4, the admin determines the playoff procedure and records the winning team and an explanation. No fixed three-hole or sudden-death rule applies. The bracket advances only after that decision is recorded. Extra tiebreak play is excluded from nine-hole player statistics.</p><h3>Team prize money</h3><p>Final playoff results determine team prizes: champion $100 per player ($400 per team), runner-up $75 per player ($300 per team), and third-place winner $50 per player ($200 per team). Four payouts per team; fourth place receives no team prize. These are separate from individual awards and skins.</p><h3>Season awards and skins</h3><p>Individual low net and Stableford awards use 100% of each round’s saved playing handicap, regardless of the team allowance. Count each player’s best 10 of 11 individual rounds, excluding the scramble. If nobody reaches 10 at season end, use best 9 with nine required; if nobody reaches nine, await an admin decision. Both categories pay the five places shown in the prize table above. Ties split the amounts for occupied places, with $0 beyond fifth. A player cannot win money from both individual awards: they keep the larger actual payout and are excluded from the other award, which passes to the next eligible finisher. Equal payouts go to low net; the player is excluded from Stableford. Weekly net skins use a fixed $80 plus carryover, per outright skin. Tied holes are canceled. Individual skins use the full saved playing handicap and hole stroke ranks. Scramble skins remain gross and are awarded to teams. Admins finalize payout rounding.</p><h3>Automatic league handicaps</h3><p>Six latest eligible individual rounds: 75% of their mean adjusted differential plus 25% of their best-three mean. With fewer rounds, use all available rounds and the best half, rounded up. Subtract the fixed zero reference, apply 90%, round and floor at zero. Updates may rise by one or fall by two strokes. Weekly difficulty is the median deviation from reliable pre-round expectations, capped at ±3; fewer than six reliable players produces zero adjustment. Historical forward-tee adjustments apply only to the 2025 seeds. All initial values require admin review before automatic updates begin.</p><p>Both playoff weeks use the same frozen handicaps. Updates resume only when the administrator explicitly enables them.</p><h3>Player statistics</h3><p>Gross totals use actual strokes. Individual net totals subtract 100% of the saved playing handicap, independently of match allowance or relative match strokes. Pars, birdies and eagles use gross scores. Stats and points appear only once every player in that match has nine valid scores (four for pairs, two for singles). Scheduled matches and missing scores never count as ties.</p></div>`;}
const SECTION_TITLES={schedule:'Schedule & results','my-schedule':'My schedule',standings:'Standings',teams:'Teams',players:'Player stats',skins:'Skins',playoffs:'Playoffs',awards:'Season awards',handicaps:'Handicaps',courses:'Courses',rules:'League rules'};
function parseLeagueRoute(hash){const [raw,n,...extra]=String(hash||'').replace(/^#/,'').split('/'),section=Object.prototype.hasOwnProperty.call(SECTION_TITLES,raw)?raw:'schedule';return {section,week:section==='schedule'&&extra.length===0&&/^\d+$/.test(n||'')&&data.Weeks.some(w=>+w.week===+n)?+n:null};}
function setScheduleWeek(value){week=value;history.pushState(null,'','#schedule/'+week);render();}
function render(){if(!model)return;const openCards=[...document.querySelectorAll('details[data-card][open]')].map(el=>el.dataset.card);const route=parseLeagueRoute(location.hash);tab=route.section;if(route.week!==null)week=route.week;else if(tab==='schedule'&&typeof history!=='undefined')history.replaceState(null,'','#schedule/'+week);if(!['standings','schedule','my-schedule','players','playoffs','awards','skins','handicaps','courses','teams','rules'].includes(tab))tab='schedule';document.title=(SECTION_TITLES[tab]||'Schedule & results')+(tab==='schedule'?' · Week '+week:'')+' | '+SITE_NAME;document.querySelector?.('.nav-more')?.classList.toggle('active',['handicaps','courses','rules'].includes(tab));document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+tab;a.classList.toggle('active',active);if(active){a.setAttribute('aria-current','page');const scroller=a.closest('.nav-links');if(scroller){const item=a.getBoundingClientRect(),box=scroller.getBoundingClientRect();if(item.left<box.left+2||item.right>box.right-28)scroller.scrollLeft+=item.left-box.left-(box.width-item.width)/2;}}else a.removeAttribute('aria-current');});try{$('view').setAttribute('aria-busy','false');$('view').setAttribute('data-section',tab);$('view').innerHTML=(model.issues.length?`<div class="notice">Schedule needs attention: ${model.issues.map(esc).join('; ')}</div>`:'')+({standings,schedule,'my-schedule':playerSchedule,teams,players,playoffs,awards:seasonAwards,skins:weeklySkins,handicaps:handicapView,courses,rules}[tab]());}catch(e){$('view').innerHTML='<div class="notice notice-error">This section could not load: '+esc(e.message)+'. Refresh the page. If this continues, check that all website update files were uploaded together.</div>';return;}document.querySelectorAll('details[data-card]').forEach(el=>{if(openCards.includes(el.dataset.card))el.open=true;});window.LiveScoring?.decorate();if($('change-player'))$('change-player').onclick=()=>{rememberPlayer('');render();($('find-player')||$('schedule-player'))?.focus();};if($('find-player'))$('find-player').onchange=e=>{rememberPlayer(e.target.value);render();};for(const [id,delta] of [['previous-week',-1],['next-week',1]])if($(id))$(id).onclick=()=>{const weeks=[...data.Weeks].sort((a,b)=>a.week-b.week),i=weeks.findIndex(w=>+w.week===week),next=weeks[i+delta];if(next){setScheduleWeek(+next.week);}};if($('current-week'))$('current-week').onclick=()=>{setScheduleWeek(upcomingWeek());};if($('schedule-player'))$('schedule-player').onchange=e=>{rememberPlayer(e.target.value);render();};if($('week'))$('week').onchange=e=>{if(tab==='schedule')setScheduleWeek(+e.target.value);else {week=+e.target.value;render();}};if($('scope'))$('scope').onchange=e=>{statScope=e.target.value;render();};if($('sort'))$('sort').onchange=e=>{sortBy=e.target.value;render();};}
function jsonp(endpoint){return new Promise((resolve,reject)=>{const url=new URL(endpoint);if(url.protocol!=='https:'||url.hostname!=='script.google.com'||!url.pathname.endsWith('/exec'))return reject(Error('Use a deployed script.google.com /exec URL in config.js'));const cb='league_'+Date.now()+'_'+Math.floor(Math.random()*100000);const s=document.createElement('script');let timer;function cleanup(){clearTimeout(timer);s.remove();delete window[cb];}window[cb]=d=>{cleanup();d.error?reject(Error(d.error)):resolve(d);};timer=setTimeout(()=>{cleanup();reject(Error('Google Sheets timed out. Check public deployment access.'));},20000);s.onerror=()=>{cleanup();reject(Error('Could not load Google Sheets. Check the deployment URL and access.'));};url.searchParams.set('callback',cb);url.searchParams.set('v',Date.now());s.src=url.href;document.head.append(s);});}
let automaticWeek=null;
function upcomingWeek(now=new Date()){
 const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);
 const part=k=>parts.find(p=>p.type===k).value,today=part('year')+'-'+part('month')+'-'+part('day');
 const weeks=[...data.Weeks].sort((a,b)=>a.week-b.week);
 return Number((weeks.find(w=>w.sat>=today)||weeks[weeks.length-1])?.week||1);
}
function selectUpcomingWeek(){const next=upcomingWeek();if(automaticWeek!==next){if(typeof location==='undefined'||parseLeagueRoute(location.hash).week===null)week=next;automaticWeek=next;}}
let lastLeagueSnapshot='';
function leagueSnapshot(next){return JSON.stringify(next);}
function showLeague(next){const snapshot=leagueSnapshot(next);if(model&&snapshot===lastLeagueSnapshot)return false;const calculated=League.calculate(next);lastLeagueSnapshot=snapshot;data=next;model=calculated;selectUpcomingWeek();renderNews();$('brand').textContent=SITE_NAME;document.title=$('brand').textContent;render();return true;}
function cacheKey(){return 'golf-league-public-v1:'+window.LEAGUE_CONFIG.endpoint;}
function restoreCache(){try{if(!window.LEAGUE_CONFIG.endpoint)return;const saved=JSON.parse(localStorage.getItem(cacheKey()));if(!saved||Date.now()-saved.at>7*86400000)return;showLeague(saved.data);$('status').textContent='Saved data from '+new Date(saved.at).toLocaleString()+ ' · Checking for updates…';}catch{}}
let loading=false,leagueLoadPromise=null,lastFreshLeagueAt=0;
function load(){if(leagueLoadPromise)return leagueLoadPromise;leagueLoadPromise=loadLeagueOnce().finally(()=>{leagueLoadPromise=null;});return leagueLoadPromise;}
async function loadLeagueOnce(){loading=true;$('refresh').disabled=true;try{const endpoint=window.LEAGUE_CONFIG.endpoint;const next=endpoint?await jsonp(endpoint):window.LEAGUE_STARTER;showLeague(next);lastFreshLeagueAt=Date.now();if(endpoint){try{localStorage.setItem(cacheKey(),JSON.stringify({at:Date.now(),data:next}));}catch{}}$('status').textContent=endpoint?'Updated '+new Date().toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}):'SETUP PREVIEW · Real season dates, placeholder names, no scores. Connect your Google Sheet to go live.';return true;}catch(e){$('status').textContent='Update failed: '+e.message+(model?' Showing the last successfully loaded data.':'');if(!model){$('view').setAttribute('aria-busy','false');$('view').innerHTML='<div class="notice notice-error">League data could not be loaded. Check the connection and try Refresh.</div>';} return false;}finally{loading=false;$('refresh').disabled=false;}}
if(typeof document!=='undefined'&&document.addEventListener)document.addEventListener('error',event=>{const img=event.target;if(img?.tagName!=='IMG')return;if(img.classList.contains('banner-photo')){img.hidden=true;img.closest('.week-banner')?.classList.add('week-banner-compact');return;}if(!img.closest('.course-entry'))return;img.hidden=true;const box=img.closest('.course-logo');if(box)box.hidden=true;},true);
function updateNavFade(){const links=document.querySelector('.nav-links');if(links)links.classList.toggle('has-more-right',links.scrollLeft+links.clientWidth<links.scrollWidth-2);}
function updateNavOffset(){updateNavFade();const nav=document.querySelector('.site-nav');if(nav)document.documentElement.style.setProperty('--nav-h',Math.ceil(nav.getBoundingClientRect().height)+'px');}
$('refresh').onclick=load;
document.querySelector('.nav-links')?.addEventListener('scroll',updateNavFade,{passive:true});
updateNavOffset();
if(typeof ResizeObserver!=='undefined'){const nav=document.querySelector('.site-nav');if(nav)new ResizeObserver(updateNavOffset).observe(nav);}
window.addEventListener('resize',updateNavOffset);
if(document.fonts?.ready)document.fonts.ready.then(updateNavOffset);
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a||a.hash==='#content')return;e.preventDefault();history.pushState(null,'',a.hash==='#schedule'?'#schedule/'+week:a.hash);document.querySelector('.nav-more')?.removeAttribute('open');render();$('view').focus({preventScroll:true});$('view').scrollIntoView({block:'start',behavior:'instant'});});
window.addEventListener('hashchange',render);window.addEventListener('popstate',render);restoreCache();load();

// Scroll only after a visitor expands a scorecard, not after live refreshes.
document.addEventListener('click',event=>{
 const summary=event.target.closest?.('.schedule-scorecard > summary');
 if(!summary||event.defaultPrevented)return;
 const card=summary.parentElement;
 requestAnimationFrame(()=>requestAnimationFrame(()=>{
  if(!card.isConnected||!card.open)return;
  const nav=document.querySelector('.site-nav');
  const offset=(nav?nav.getBoundingClientRect().height:0)+12;
  const top=Math.max(0,window.scrollY+card.getBoundingClientRect().top-offset);
  window.scrollTo({top,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
 }));
});
